def max_sum(arr):
    if not arr:
        return 0

    n = len(arr)
    increasing = list(arr)
    decreasing = list(arr)

    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                increasing[i] = max(increasing[i], increasing[j] + arr[i])

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                decreasing[i] = max(decreasing[i], decreasing[j] + arr[i])

    return max(increasing[i] + decreasing[i] - arr[i] for i in range(n))
